def create_workflow(nodes, connections=None, **_extra):
    import json, os, datetime, hashlib, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0358000" if __import__("os").path.isdir("./environment_mix/0358000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _stable_json(obj):
        return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

    def _canonicalize(nodes_in, conns_in):
        # nodes canonical: list of {type,name,parameters} sorted by name
        canon_nodes = []
        for n in nodes_in:
            canon_nodes.append({
                "type": n.get("type"),
                "name": n.get("name"),
                "parameters": n.get("parameters", None) if isinstance(n.get("parameters", None), dict) else None,
            })
        canon_nodes.sort(key=lambda x: x["name"])

        canon_conns = []
        for c in conns_in:
            so = c.get("sourceOutput", 0)
            ti = c.get("targetInput", 0)
            canon_conns.append({
                "source": c.get("source"),
                "target": c.get("target"),
                "sourceOutput": so,
                "targetInput": ti,
            })
        canon_conns.sort(key=lambda x: (x["source"], x["target"], x["sourceOutput"], x["targetInput"]))
        return {"nodes": canon_nodes, "connections": canon_conns}

    start = time.time()

    # Load stores
    workflows = _load("workflows.json")
    wf_nodes = _load("workflow_nodes.json")
    wf_conns = _load("workflow_connections.json")
    create_reqs = _load("workflow_create_requests.json")
    api_keys = _load("api_keys.json")

    # Minimal request logging if a request log collection exists (schema didn't define one).
    # Enforce quota/rate using api_keys collection as specified.

    # Validate input types
    if not isinstance(nodes, list):
        return _err("VALIDATION_ERROR", "nodes must be an array")
    if len(nodes) < 1:
        # Must also create request row -> failed
        req_id = _gen_id("wcr")
        now = _now()
        create_reqs.append({
            "id": req_id,
            "idempotency_key": None,
            "workflow_id": None,
            "request_nodes": nodes if isinstance(nodes, list) else [],
            "request_connections": [] if connections is None else connections,
            "status": "failed",
            "error_message": "request_nodes length must be >= 1",
            "created_at": now,
            "updated_at": now,
        })
        _save("workflow_create_requests.json", create_reqs)
        return _err("VALIDATION_ERROR", "nodes must contain at least 1 node", request_id=req_id)

    if connections is None:
        connections_list = []
    else:
        if not isinstance(connections, list):
            return _err("VALIDATION_ERROR", "connections must be an array when provided")
        connections_list = connections

    # Find an authorized active API key (ambient auth). Must have status=active.
    # If none exists, refuse.
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available")

    # Choose a key that can satisfy quota for a successful create (if it proceeds).
    # Rolling day window based on window_start_at. Reset if >= 24h.
    now_dt = datetime.datetime.utcnow()
    chosen_key = None
    for k in active_keys:
        limit = k.get("daily_create_limit")
        used = k.get("daily_create_used")
        if not isinstance(limit, int) or not isinstance(used, int):
            continue
        ws = _parse_dt(k.get("window_start_at"))
        if ws is None:
            # treat as needs reset to now
            ws = now_dt
            k["window_start_at"] = _now()
            k["daily_create_used"] = 0
            used = 0
        if (now_dt - ws) >= datetime.timedelta(days=1):
            k["window_start_at"] = _now()
            k["daily_create_used"] = 0
            used = 0
        if used < limit:
            chosen_key = k
            break

    if chosen_key is None:
        # persist any window resets possibly done above
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily create_workflow limit exceeded")

    # Validate nodes content and uniqueness of names
    node_names = []
    node_name_set = set()
    norm_nodes = []
    for i, n in enumerate(nodes):
        if not isinstance(n, dict):
            return _err("VALIDATION_ERROR", f"nodes[{i}] must be an object")
        if "type" not in n or "name" not in n:
            return _err("VALIDATION_ERROR", f"nodes[{i}] must include required fields: type, name")
        nt = n.get("type")
        nn = n.get("name")
        if not isinstance(nt, str) or not (1 <= len(nt) <= 255):
            return _err("VALIDATION_ERROR", f"nodes[{i}].type must be a string length 1..255")
        if not isinstance(nn, str) or not (1 <= len(nn) <= 255):
            return _err("VALIDATION_ERROR", f"nodes[{i}].name must be a string length 1..255")
        if nn in node_name_set:
            # Create request must be marked failed
            req_id = _gen_id("wcr")
            now = _now()
            create_reqs.append({
                "id": req_id,
                "idempotency_key": None,
                "workflow_id": None,
                "request_nodes": nodes,
                "request_connections": connections_list,
                "status": "failed",
                "error_message": f"Duplicate node name within workflow: {nn}",
                "created_at": now,
                "updated_at": now,
            })
            _save("workflow_create_requests.json", create_reqs)
            return _err("VALIDATION_ERROR", "Each nodes[].name must be unique within the workflow", node_name=nn, request_id=req_id)
        node_name_set.add(nn)
        node_names.append(nn)
        params = n.get("parameters", None)
        if params is not None and not isinstance(params, dict):
            return _err("VALIDATION_ERROR", f"nodes[{i}].parameters must be an object when provided")
        norm_nodes.append({"type": nt, "name": nn, "parameters": params})

    # Validate connections: references by name must exist; defaults for outputs/inputs
    norm_conns = []
    for i, c in enumerate(connections_list):
        if not isinstance(c, dict):
            return _err("VALIDATION_ERROR", f"connections[{i}] must be an object")
        if "source" not in c or "target" not in c:
            return _err("VALIDATION_ERROR", f"connections[{i}] must include required fields: source, target")
        s = c.get("source")
        t = c.get("target")
        if not isinstance(s, str) or not s:
            return _err("VALIDATION_ERROR", f"connections[{i}].source must be a non-empty string")
        if not isinstance(t, str) or not t:
            return _err("VALIDATION_ERROR", f"connections[{i}].target must be a non-empty string")
        so = c.get("sourceOutput", 0)
        ti = c.get("targetInput", 0)

        # must be integers >= 0 (tool schema says number; business says integer)
        if isinstance(so, bool) or not (isinstance(so, int) or (isinstance(so, float) and so.is_integer())):
            return _err("VALIDATION_ERROR", f"connections[{i}].sourceOutput must be an integer >= 0")
        if isinstance(ti, bool) or not (isinstance(ti, int) or (isinstance(ti, float) and ti.is_integer())):
            return _err("VALIDATION_ERROR", f"connections[{i}].targetInput must be an integer >= 0")
        so = int(so)
        ti = int(ti)
        if so < 0:
            return _err("VALIDATION_ERROR", f"connections[{i}].sourceOutput must be >= 0")
        if ti < 0:
            return _err("VALIDATION_ERROR", f"connections[{i}].targetInput must be >= 0")

        if s not in node_name_set or t not in node_name_set:
            req_id = _gen_id("wcr")
            now = _now()
            create_reqs.append({
                "id": req_id,
                "idempotency_key": None,
                "workflow_id": None,
                "request_nodes": nodes,
                "request_connections": connections_list,
                "status": "failed",
                "error_message": f"Connection references unknown node name(s): source={s}, target={t}",
                "created_at": now,
                "updated_at": now,
            })
            _save("workflow_create_requests.json", create_reqs)
            return _err("VALIDATION_ERROR", "connections[].source and connections[].target must match a nodes[].name within the same request",
                        connection_index=i, request_id=req_id)
        norm_conns.append({"source": s, "target": t, "sourceOutput": so, "targetInput": ti})

    # Create workflow_create_requests row (no idempotency_key parameter exposed -> store null)
    req_id = _gen_id("wcr")
    now = _now()
    req_row = {
        "id": req_id,
        "idempotency_key": None,
        "workflow_id": None,
        "request_nodes": nodes,
        "request_connections": connections_list,
        "status": "received",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    create_reqs.append(req_row)
    _save("workflow_create_requests.json", create_reqs)

    # Transition received -> validated
    req_row["status"] = "validated"
    req_row["updated_at"] = _now()
    _save("workflow_create_requests.json", create_reqs)

    # Compute definition_hash from canonical JSON of nodes and connections including defaults.
    canonical = _canonicalize(norm_nodes, norm_conns)
    canon_str = _stable_json(canonical)
    definition_hash = hashlib.sha256(canon_str.encode("utf-8")).hexdigest()

    # Prevent duplicates where status != deleted
    for w in workflows:
        if not isinstance(w, dict):
            continue
        if w.get("status") != "deleted" and w.get("definition_hash") == definition_hash:
            # Mark request failed, no workflow created
            req_row["status"] = "failed"
            req_row["error_message"] = "Duplicate workflow definition_hash exists for non-deleted workflow"
            req_row["updated_at"] = _now()
            _save("workflow_create_requests.json", create_reqs)
            return _err("CONFLICT", "Duplicate workflow definition (definition_hash) already exists", definition_hash=definition_hash, request_id=req_id)

    # Re-check quota just before persisting; we already chose a key with capacity, but window may have been reset above.
    limit = chosen_key.get("daily_create_limit")
    used = chosen_key.get("daily_create_used")
    if not isinstance(limit, int) or not isinstance(used, int):
        req_row["status"] = "failed"
        req_row["error_message"] = "API key quota configuration invalid"
        req_row["updated_at"] = _now()
        _save("workflow_create_requests.json", create_reqs)
        return _err("UNAUTHORIZED", "API key configuration invalid")
    if used + 1 > limit:
        req_row["status"] = "failed"
        req_row["error_message"] = "Daily create_workflow limit exceeded"
        req_row["updated_at"] = _now()
        _save("workflow_create_requests.json", create_reqs)
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily create_workflow limit exceeded", request_id=req_id)

    # Persist atomically: prepare rows first, validate self-loop/uniques among new connections, then append and save.
    workflow_id = _gen_id("wf")
    ts = _now()

    # Create nodes rows
    new_node_rows = []
    name_to_id = {}
    for n in norm_nodes:
        nid = _gen_id("wfn")
        name_to_id[n["name"]] = nid
        new_node_rows.append({
            "id": nid,
            "workflow_id": workflow_id,
            "node_type": n["type"],
            "node_name": n["name"],
            "parameters": n["parameters"],
            "created_at": ts,
            "updated_at": ts,
            "status": "configured",
        })

    # Ensure unique(workflow_id, node_name) - new workflow, so only internal uniqueness needed (already checked)
    # Create connections rows, resolve names to ids, enforce constraints
    new_conn_rows = []
    conn_unique = set()
    for c in norm_conns:
        sid = name_to_id.get(c["source"])
        tid = name_to_id.get(c["target"])
        if sid is None or tid is None:
            # Shouldn't happen due to earlier validation, but treat as failure without partial commit
            req_row["status"] = "failed"
            req_row["error_message"] = "Internal name resolution failed"
            req_row["updated_at"] = _now()
            _save("workflow_create_requests.json", create_reqs)
            return _err("VALIDATION_ERROR", "Connection name resolution failed", request_id=req_id)

        if sid == tid:
            req_row["status"] = "failed"
            req_row["error_message"] = "Connection cannot be a self-loop"
            req_row["updated_at"] = _now()
            _save("workflow_create_requests.json", create_reqs)
            return _err("VALIDATION_ERROR", "A connection cannot be a self-loop", request_id=req_id)

        tup = (sid, tid, c["sourceOutput"], c["targetInput"])
        if tup in conn_unique:
            req_row["status"] = "failed"
            req_row["error_message"] = "Duplicate connection in request"
            req_row["updated_at"] = _now()
            _save("workflow_create_requests.json", create_reqs)
            return _err("VALIDATION_ERROR", "Duplicate connection within workflow request", request_id=req_id)
        conn_unique.add(tup)

        cid = _gen_id("wfc")
        new_conn_rows.append({
            "id": cid,
            "workflow_id": workflow_id,
            "source_node_id": sid,
            "target_node_id": tid,
            "source_node_name": c["source"],
            "target_node_name": c["target"],
            "source_output": c["sourceOutput"],
            "target_input": c["targetInput"],
            "created_at": ts,
            "updated_at": ts,
            "status": "valid",
        })

    # Persist workflow row
    new_wf_row = {
        "id": workflow_id,
        "status": "draft",
        "version": 1,
        "node_count": len(new_node_rows),
        "connection_count": len(new_conn_rows),
        "definition_hash": definition_hash,
        "created_at": ts,
        "updated_at": ts,
    }

    # Commit all changes
    workflows.append(new_wf_row)
    wf_nodes.extend(new_node_rows)
    wf_conns.extend(new_conn_rows)

    # Update request to persisted
    req_row["status"] = "persisted"
    req_row["workflow_id"] = workflow_id
    req_row["error_message"] = None
    req_row["updated_at"] = _now()

    # Increment usage/counters for successful create
    chosen_key["daily_create_used"] = int(chosen_key.get("daily_create_used", 0)) + 1
    chosen_key["last_used_at"] = _now()
    chosen_key["updated_at"] = _now()

    # Save all
    _save("workflows.json", workflows)
    _save("workflow_nodes.json", wf_nodes)
    _save("workflow_connections.json", wf_conns)
    _save("workflow_create_requests.json", create_reqs)
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - start) * 1000)

    # Return persisted definition
    return {
        "workflow": new_wf_row,
        "nodes": new_node_rows,
        "connections": new_conn_rows,
        "request": {
            "id": req_row["id"],
            "status": req_row["status"],
            "workflow_id": req_row["workflow_id"],
            "created_at": req_row["created_at"],
            "updated_at": req_row["updated_at"],
        },
        "usage": {
            "api_key_id": chosen_key.get("id"),
            "daily_create_limit": chosen_key.get("daily_create_limit"),
            "daily_create_used": chosen_key.get("daily_create_used"),
            "window_start_at": chosen_key.get("window_start_at"),
            "last_used_at": chosen_key.get("last_used_at"),
        },
        "meta": {
            "latency_ms": latency_ms,
        },
    }
